select
admins.*
from admins admins

    and admins.id = #{id}
    and admins.ad_name like concat('%',#{adName},'%')
    and admins.ad_username = #{adUsername}
    and admins.ad_password = #{adPassword}
    and admins.ad_header = #{adHeader}


    limit #{current},#{pageSize}

select count(*) from admins admins

    and admins.id = #{id}
    and admins.ad_name like concat('%',#{adName},'%')
    and admins.ad_username = #{adUsername}
    and admins.ad_password = #{adPassword}
    and admins.ad_header = #{adHeader}
